rid-column:1/-1}.master-entity-card .field{min-width:0}.master-entity-card .field-hint{font-size:11px;color:#34473c}.master-entity-card .mr-msg{display:block;color:#672329;font-size:12px}.master-entity-card .input-dialog input,.master-entity-card .input-dialog textarea{width:100%;min-height:44px}.import-preview-table-wrap{max-height:300px;overflow:auto;margin-top:16px}.master-table-scroll{border:1px solid var(--border-card);border-radius:12px}.master-entity-card td:last-child{white-space:nowrap}.master-entity-card .input-dialog td{white-space:normal}
